// GQ has no arithmetic operators, so `age * 2` and `2026 - age` cannot be
// expressed. This is the closest valid query:
// - the caller passes $min_age = ceil(min / 2), which is equivalent to
//   age * 2 >= min for integer ages;
// - the caller computes twice = age * 2 and born_about = 2026 - age from the
//   returned age.
query doubled_age_people($min_age: I32) {
    match {
        $p: Person
        $p.age >= $min_age
    }
    return {
        $p.name,
        $p.age
    }
}
